const d = $('Get Digest').first().json;
const issues = ($('Sentry Issues').all() || []).length;
const t = d.trading, e = d.equity;
const icon = d.status === 'critical' ? '🚨' : d.status === 'warning' ? '⚠️' : '✅';
const sign = n => (n >= 0 ? '+' : '') + n;
let msg = `${icon} *Polybot daily* (${d.strategy_version})\n\n`;
msg += `*Equity* $${e.current.toLocaleString()}  (${sign(e.change)} / ${sign(e.change_pct)}%)\n`;
msg += `Peak $${e.peak.toLocaleString()}  ·  drawdown ${e.drawdown_pct}%\n\n`;
msg += `*Trading (24h)*\n`;
msg += `${t.trades} trades · ${t.win_rate}% WR · P&L ${sign(t.pnl)}\n`;
msg += `Break-even ${t.break_even_win_rate}% → margin ${sign(t.margin_pp)}pp\n`;
msg += `Payoff ${t.payoff_ratio}:1  (avg win ${sign(t.avg_win)} / avg loss ${t.avg_loss})\n\n`;
msg += `*Open* ${d.open_positions.count} positions · $${d.open_positions.exposure_usd}\n`;
if (d.exits.fired > 0) {
  msg += `*Exits* ${d.exits.fired} fired (${sign(d.exits.pnl)})`;
  if (d.exits.hold_shadow_resolved > 0) msg += ` — ${d.exits.verdict}`;
  msg += `\n`;
}
msg += `*Sentry* ${issues} unresolved issue(s)\n`;
if (d.alerts.length) {
  msg += `\n*Alerts*\n` + d.alerts.map(a => `• ${a.message}`).join('\n');
}
return [{ json: { text: msg } }];
